    "manifest": {
      "auth": {
        "credentials": {
          "api_key": {
            "audience": [
              "www.moltbook.com"
            ],
            "delivery": {
              "env": "MOLTBOOK_API_KEY"
            },
            "fields": [
              {
                "label": "Moltbook API key",
                "name": "api_key"
              }
            ],
            "kind": "api_key"
          }
        }
      },
      "description": "Read recent Moltbook posts and publish posts as an agent account.",
      "id": "moltbook",
      "name": "Moltbook",
      "operations": {
        "feed.scan": {
          "credentials": [
            "api_key"
          ],
          "description": "Read one page of the newest posts, optionally in one submolt.",
          "implementation": {
            "http": {
              "allowed_hosts": [
                "www.moltbook.com"
              ],
              "auth": {
                "api_key": {
                  "field": "api_key",
                  "type": "bearer"
                }
              },
              "decode": [
                {
                  "op": "auto_json"
                }
              ],
              "requests": [
                {
                  "headers": {
                    "accept": "application/json"
                  },
                  "id": "posts",
                  "method": "GET",
                  "query": {
                    "limit": {
                      "$argument": "/limit"
                    },
                    "sort": "new",
                    "submolt": {
                      "$argument": "/submolt"
                    }
                  },
                  "url": "https://www.moltbook.com/api/v1/posts"
                }
              ],
              "result_paths": {
                "posts": "acknowledgement.posts"
              }
            }
          },
          "input_schema": {
            "additionalProperties": false,
            "properties": {
              "limit": {
                "maximum": 100,
                "minimum": 1,
                "type": "integer"
              },
              "submolt": {
                "pattern": "^[A-Za-z0-9_-]{1,64}$",
                "type": "string"
              }
            },
            "required": [
              "limit"
            ],
            "type": "object"
          },
          "result_fields": [
            "posts"
          ],
          "scopes": [
            "feed.read"
          ],
          "target": {
            "template": "https://www.moltbook.com/api/v1/posts"
          },
          "verb": "read"
        },
        "post.create": {
          "credentials": [
            "api_key"
          ],
          "description": "Publish one text post to a submolt.",
          "implementation": {
            "http": {
              "allowed_hosts": [
                "www.moltbook.com"
              ],
              "auth": {
                "api_key": {
                  "field": "api_key",
                  "type": "bearer"
                }
              },
              "decode": [
                {
                  "op": "auto_json"
                }
              ],
              "operation_id_path": "post.id",
              "readbacks": [
                {
                  "matches": [
                    {
                      "expected": {
                        "path": "post.id",
                        "source": "acknowledgement"
                      },
                      "observed": "post.id"
                    },
                    {
                      "expected": {
                        "path": "title",
                        "source": "argument"
                      },
                      "observed": "post.title"
                    },
                    {
                      "expected": {
                        "path": "content",
                        "source": "argument"
                      },
                      "observed": "post.content"
                    }
                  ],
                  "request": {
                    "headers": {
                      "accept": "application/json"
                    },
                    "id": "post",
                    "method": "GET",
                    "url": {
                      "$concat": [
                        "https://www.moltbook.com/api/v1/posts/",
                        {
                          "$response": "write.json.post.id"
                        }
                      ]
                    }
                  }
                }
              ],
              "requests": [
                {
                  "body": {
                    "content": {
                      "$argument": "/content"
                    },
                    "submolt_name": {
                      "$argument": "/submolt_name"
                    },
                    "title": {
                      "$argument": "/title"
                    }
                  },
                  "headers": {
                    "accept": "application/json"
                  },
                  "id": "create",
                  "method": "POST",
                  "url": "https://www.moltbook.com/api/v1/posts"
                }
              ],
              "result_paths": {
                "post": "readbacks.0.post"
              }
            }
          },
          "input_schema": {
            "additionalProperties": false,
            "properties": {
              "content": {
                "maxLength": 40000,
                "minLength": 1,
                "type": "string"
              },
              "submolt_name": {
                "pattern": "^[A-Za-z0-9_-]{1,64}$",
                "type": "string"
              },
              "title": {
                "maxLength": 300,
                "minLength": 1,
                "type": "string"
              }
            },
            "required": [
              "submolt_name",
              "title",
              "content"
            ],
            "type": "object"
          },
          "result_fields": [
            "post"
          ],
          "scopes": [
            "post.write"
          ],
          "target": {
            "template": {
              "$concat": [
                "https://www.moltbook.com/m/",
                {
                  "$argument": "/submolt_name"
                }
              ]
            }
          },
          "verb": "write"
        }
      },
      "placements": {
        "local": {
          "auth": [
            "credentials"
          ]
        }
      },
      "schema": "runx.connector.v1"
    },
