    "manifest": {
      "auth": {
        "none": {}
      },
      "description": "Deliver a governed handoff to an n8n Cloud workflow webhook.",
      "id": "n8n",
      "name": "n8n",
      "operations": {
        "workflow.invoke": {
          "approval": "required",
          "description": "Deliver one handoff to an n8n Cloud workflow webhook; the workflow's answer is the acknowledgement and n8n offers no readback.",
          "guarantees": {
            "readback": "unavailable"
          },
          "implementation": {
            "http": {
              "allowed_hosts": [
                "*.app.n8n.cloud"
              ],
              "decode": [
                {
                  "op": "auto_json"
                }
              ],
              "requests": [
                {
                  "body": {
                    "$argument": "/delivery"
                  },
                  "headers": {
                    "accept": "application/json",
                    "x-runx-event-id": {
                      "$argument": "/delivery/event_id"
                    },
                    "x-runx-handoff-audience": {
                      "$argument": "/delivery/handoff_audience"
                    },
                    "x-runx-handoff-scope": {
                      "$argument": "/delivery/handoff_scope"
                    }
                  },
                  "id": "deliver",
                  "method": "POST",
                  "url": {
                    "$concat": [
                      "https://",
                      {
                        "$argument": "/webhook_host"
                      },
                      "/webhook/",
                      {
                        "$argument": "/workflow_slug"
                      }
                    ]
                  }
                }
              ],
              "result_paths": {
                "acknowledgement": "acknowledgement"
              }
            }
          },
          "input_schema": {
            "additionalProperties": false,
            "properties": {
              "delivery": {
                "properties": {
                  "event_id": {
                    "pattern": "^[A-Za-z0-9._:-]{3,200}$",
                    "type": "string"
                  },
                  "handoff_audience": {
                    "pattern": "^n8n:",
                    "type": "string"
                  },
                  "handoff_scope": {
                    "const": "orchestrator.n8n.workflow.invoke"
                  },
                  "idempotency_key": {
                    "type": "string"
                  },
                  "payload": {}
                },
                "required": [
                  "event_id",
                  "handoff_scope",
                  "handoff_audience",
                  "idempotency_key",
                  "payload"
                ],
                "type": "object"
              },
              "webhook_host": {
                "pattern": "^[a-z0-9][a-z0-9-]{0,62}\\.app\\.n8n\\.cloud$",
                "type": "string"
              },
              "workflow_slug": {
                "maxLength": 128,
                "pattern": "^[A-Za-z0-9_-]+$",
                "type": "string"
              }
            },
            "required": [
              "webhook_host",
              "workflow_slug",
              "delivery"
            ],
            "type": "object"
          },
          "result_fields": [
            "acknowledgement"
          ],
          "scopes": [
            "orchestrator.n8n.workflow.invoke"
          ],
          "target": {
            "template": {
              "$concat": [
                "https://",
                {
                  "$argument": "/webhook_host"
                },
                "/webhook/",
                {
                  "$argument": "/workflow_slug"
                }
              ]
            }
          },
          "verb": "write"
        }
      },
      "placements": {
        "local": {
          "auth": [
            "none"
          ]
        }
      },
      "schema": "runx.connector.v1"
    },
