    "manifest": {
      "auth": {
        "none": {}
      },
      "description": "Resolve US gridpoints and read National Weather Service forecasts.",
      "id": "national-weather-service",
      "name": "National Weather Service",
      "operations": {
        "forecast.read": {
          "description": "Read the forecast for one NWS office gridpoint.",
          "implementation": {
            "http": {
              "allowed_hosts": [
                "api.weather.gov"
              ],
              "decode": [
                {
                  "op": "auto_json"
                }
              ],
              "requests": [
                {
                  "headers": {
                    "accept": "application/geo+json, application/json",
                    "user-agent": "runx-weather-catalog/0.1 (https://github.com/runxhq/runx)"
                  },
                  "id": "forecast",
                  "method": "GET",
                  "url": {
                    "$concat": [
                      "https://api.weather.gov/gridpoints/",
                      {
                        "$argument": "/office"
                      },
                      "/",
                      {
                        "$argument": "/grid_x"
                      },
                      ",",
                      {
                        "$argument": "/grid_y"
                      },
                      "/forecast"
                    ]
                  }
                }
              ],
              "result_paths": {
                "forecast": "acknowledgement"
              }
            }
          },
          "input_schema": {
            "additionalProperties": false,
            "properties": {
              "grid_x": {
                "pattern": "^[0-9]{1,3}$",
                "type": "string"
              },
              "grid_y": {
                "pattern": "^[0-9]{1,3}$",
                "type": "string"
              },
              "office": {
                "pattern": "^[A-Z]{3}$",
                "type": "string"
              }
            },
            "required": [
              "office",
              "grid_x",
              "grid_y"
            ],
            "type": "object"
          },
          "result_fields": [
            "forecast"
          ],
          "scopes": [
            "weather.read"
          ],
          "target": {
            "template": "https://api.weather.gov/gridpoints"
          },
          "verb": "read"
        },
        "points.read": {
          "description": "Resolve a latitude and longitude to its NWS office and gridpoint.",
          "implementation": {
            "http": {
              "allowed_hosts": [
                "api.weather.gov"
              ],
              "decode": [
                {
                  "op": "auto_json"
                }
              ],
              "requests": [
                {
                  "headers": {
                    "accept": "application/geo+json, application/json",
                    "user-agent": "runx-weather-catalog/0.1 (https://github.com/runxhq/runx)"
                  },
                  "id": "points",
                  "method": "GET",
                  "url": {
                    "$concat": [
                      "https://api.weather.gov/points/",
                      {
                        "$argument": "/lat"
                      },
                      ",",
                      {
                        "$argument": "/lon"
                      }
                    ]
                  }
                }
              ],
              "result_paths": {
                "points": "acknowledgement"
              }
            }
          },
          "input_schema": {
            "additionalProperties": false,
            "properties": {
              "lat": {
                "pattern": "^-?[0-9]{1,2}(\\.[0-9]{1,4})?$",
                "type": "string"
              },
              "lon": {
                "pattern": "^-?[0-9]{1,3}(\\.[0-9]{1,4})?$",
                "type": "string"
              }
            },
            "required": [
              "lat",
              "lon"
            ],
            "type": "object"
          },
          "result_fields": [
            "points"
          ],
          "scopes": [
            "weather.read"
          ],
          "target": {
            "template": "https://api.weather.gov/points"
          },
          "verb": "read"
        }
      },
      "placements": {
        "local": {
          "auth": [
            "none"
          ]
        }
      },
      "schema": "runx.connector.v1"
    },
